const stagePanel=document.createElement('aside');stagePanel.id='stage0-editor-matrix';stagePanel.style.cssText='position:fixed;left:8px;bottom:8px;z-index:99999;background:#fff;color:#111;padding:10px;max-width:520px;max-height:38vh;overflow:auto;font:12px sans-serif';
