const matrixResults=[],matrixFilter=new URLSearchParams(location.search).get('case'),q=s=>{const n=document.querySelector(s);if(!n)throw Error('Controle ausente: '+s);const resourcePage=n.closest('#scene-left-resources-page');if(resourcePage?.hidden)document.querySelector('#scene-left-resources')?.click();return n;},read=()=>window.Stage0EditorRead(),assert=(x,m)=>{if(!x)throw Error(m);},same=(a,b)=>assert(JSON.stringify(a)===JSON.stringify(b),'Dados divergentes: '+JSON.stringify({actual:a,expected:b})),pause=()=>new Promise(r=>setTimeout(r,20));
