async function until(fn){for(let i=0;i<250;i++){if(fn())return;await pause();}throw Error('Estado não chegou ao esperado');}
function click(s){const n=q(s);assert(!n.disabled,'Controle desabilitado: '+s);n.click();}
function change(s,value,type='change'){const n=q(s);assert(!n.disabled,'Campo desabilitado: '+s);n.value=String(value);n.dispatchEvent(new Event(type,{bubbles:true}));}
